import { createServer } from "node:http";
import { readFileSync, existsSync } from "node:fs";
import { extname, join } from "node:path";
import { createRequire } from "node:module";

const require = createRequire("/Users/sinchunyeung/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/package.json");
const { chromium } = require("playwright");

const WEB = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".png": "image/png",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json",
};

function makeStep(streamIdx, pi, p0) {
  return {
    stream_idx: streamIdx,
    pi,
    Gi: [
      [pi[0] - 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] + 0.4],
      [pi[0] - 0.4, pi[1] + 0.4],
    ],
    buffer: [p0, pi],
    candidates: [{ grid_pt_idx: 0, alive: true, F: [], S: [] }],
  };
}

const p0 = [0, 0];
const p1 = [2, 1];
const p2 = [4, 0];
const header = {
  type: "header",
  eps: 0.9,
  delta: 500,
  grid_val: 12.5,
  r_val: 8.2,
  expected_frechet: 1.25,
  bbox: [-1, -1, 6, 3],
  stream: [p0, p1, p2],
};
const prefix = {
  type: "prefix",
  data: {
    start_idx: 0,
    end_idx: 2,
    p0,
    steps: [makeStep(1, p1, p0), makeStep(2, p2, p0)],
  },
};
const done = {
  type: "done",
  time_ms: 12.4,
  simplified: [p0, p2],
  frechet_distance: 0.41,
};
const ndjson = [header, prefix, done].map((o) => JSON.stringify(o)).join("\n") + "\n";

const server = createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [{ id: 1, label: "Demo", n_points: 3 }] }));
    return;
  }
  if (url.pathname === "/api/trace/1" || url.pathname === "/api/trace") {
    res.writeHead(200, { "Content-Type": "application/x-ndjson" });
    res.end(ndjson);
    return;
  }
  if (url.pathname === "/api/frechet") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ distance: 0.4123 }));
    return;
  }
  const filePath = join(WEB, url.pathname === "/" ? "index.html" : url.pathname);
  if (!filePath.startsWith(WEB) || !existsSync(filePath)) {
    res.writeHead(404);
    res.end("not found");
    return;
  }
  res.writeHead(200, { "Content-Type": MIME[extname(filePath)] || "text/plain" });
  res.end(readFileSync(filePath));
});

function overflowReport(box, vw, vh) {
  if (!box) return null;
  return {
    text: (box.text || "").slice(0, 80),
    w: Math.round(box.w),
    h: Math.round(box.h),
    x: Math.round(box.x),
    y: Math.round(box.y),
    right: Math.round(box.x + box.w),
    overflowRight: box.x + box.w > vw + 1,
    overflowBottom: box.y + box.h > vh + 1,
    sw: box.sw,
    sh: box.sh,
    innerOverflow: box.sw > box.cw + 1 || box.sh > box.ch + 1,
  };
}

async function measure(page) {
  await page.waitForTimeout(800);
  if (page.evaluate) {
    try {
      await page.evaluate(() => window.MathJax?.typesetPromise?.());
    } catch {}
  }
  return page.evaluate(() => {
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const box = (el) => {
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return {
        x: r.x, y: r.y, w: r.width, h: r.height,
        sw: el.scrollWidth, sh: el.scrollHeight,
        cw: el.clientWidth, ch: el.clientHeight,
        text: (el.innerText || "").replace(/\s+/g, " ").trim(),
      };
    };
    const overflows = [];
    document.querySelectorAll("body *").forEach((el) => {
      if (!(el instanceof HTMLElement)) return;
      if (el.id === "tracePicker" || el.closest("#tracePicker")) return;
      const r = el.getBoundingClientRect();
      if (r.width < 2 && r.height < 2) return;
      const right = r.x + r.width;
      if (right > vw + 2 && getComputedStyle(el).position !== "fixed") {
        overflows.push({
          id: el.id, cls: el.className, tag: el.tagName,
          right: Math.round(right), w: Math.round(r.width), x: Math.round(r.x),
          text: (el.innerText || "").replace(/\s+/g, " ").trim().slice(0, 60),
        });
      }
    });
    const layers = document.getElementById("layersSection");
    const rows = [...document.querySelectorAll("#layersSection .toggle-row")].map((row) => {
      const r = row.getBoundingClientRect();
      const label = row.querySelector("label");
      const lr = label ? label.getBoundingClientRect() : null;
      return {
        text: (row.innerText || "").replace(/\s+/g, " ").trim(),
        display: getComputedStyle(row).display,
        w: Math.round(r.width),
        x: Math.round(r.x),
        right: Math.round(r.x + r.width),
        sw: row.scrollWidth,
        cw: row.clientWidth,
        labelW: lr ? Math.round(lr.width) : null,
        labelSw: label ? label.scrollWidth : null,
        labelOverflow: label ? label.scrollWidth > label.clientWidth + 1 : false,
        mj: [...row.querySelectorAll(".MathJax, mjx-container")].map((n) => {
          const b = n.getBoundingClientRect();
          return { w: Math.round(b.width), text: (n.textContent || "").slice(0, 40) };
        }),
      };
    });
    const pb = document.getElementById("playbackBar");
    const pbKids = pb ? [...pb.children].map((c) => {
      const r = c.getBoundingClientRect();
      return { cls: c.className, tag: c.tagName, x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
    }) : [];
    const header = document.querySelector("header");
    const params = document.getElementById("paramsBar");
    const sidebar = document.getElementById("sidebar");
    return {
      vw, vh,
      scrollW: document.documentElement.scrollWidth,
      scrollH: document.documentElement.scrollHeight,
      pageOverflowX: document.documentElement.scrollWidth > vw + 1,
      headerH: header ? Math.round(header.getBoundingClientRect().height) : null,
      params: box(params),
      playback: box(pb),
      playbackKids: pbKids,
      playbackWrap: pbKids.length > 1 && new Set(pbKids.filter(k => k.w > 4).map(k => k.y)).size > 1,
      sidebar: box(sidebar),
      layers: box(layers),
      layersOpen: layers ? layers.classList.contains("layers-open") : false,
      rows,
      overflows: overflows.slice(0, 20),
    };
  });
}

async function loadTrace(page) {
  await page.selectOption("#traceSelect", "1");
  await page.click("#loadBtn");
  await page.waitForSelector("body.playback-ready", { timeout: 8000 });
  await page.waitForTimeout(400);
}

function summarize(label, report) {
  return {
    label,
    vw: report.vw,
    pageOverflowX: report.pageOverflowX,
    scrollW: report.scrollW,
    headerH: report.headerH,
    playbackH: report.playback && Math.round(report.playback.h),
    playbackWrap: report.playbackWrap,
    playbackW: report.playback && Math.round(report.playback.w),
    layersW: report.layers && Math.round(report.layers.w),
    layersInnerOverflow: report.layers && (report.layers.sw > report.layers.cw + 1),
    rowOverflows: report.rows.filter((r) => r.labelOverflow || r.sw > r.cw + 1 || r.right > report.vw + 1),
    overflowEls: report.overflows,
    longestRow: report.rows.reduce((a, r) => (r.labelSw || 0) > (a?.labelSw || 0) ? r : a, null),
  };
}

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const port = server.address().port;
const browser = await chromium.launch({ channel: "chrome" });

try {
  const out = {};

  // Desktop 1280
  {
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1280, height: 800 });
    await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "domcontentloaded" });
    await loadTrace(page);
    const report = await measure(page);
    out.desktop1280 = summarize("desktop1280", report);
    out.desktop1280.rawPlaybackKids = report.playbackKids;
    out.desktop1280.rows = report.rows.map((r) => ({
      text: r.text.slice(0, 70),
      labelSw: r.labelSw,
      labelW: r.labelW,
      overflow: r.labelOverflow,
      mj: r.mj,
    }));
    await page.close();
  }

  // Desktop 1024
  {
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1024, height: 768 });
    await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "domcontentloaded" });
    await loadTrace(page);
    const report = await measure(page);
    out.desktop1024 = summarize("desktop1024", report);
    out.desktop1024.rawPlaybackKids = report.playbackKids;
    await page.close();
  }

  // Desktop 900
  {
    const page = await browser.newPage();
    await page.setViewportSize({ width: 900, height: 700 });
    await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "domcontentloaded" });
    await loadTrace(page);
    const report = await measure(page);
    out.desktop900 = summarize("desktop900", report);
    out.desktop900.rawPlaybackKids = report.playbackKids;
    await page.close();
  }

  // Mobile 390 layers closed then open
  {
    const page = await browser.newPage();
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "domcontentloaded" });
    await loadTrace(page);
    const closed = await measure(page);
    out.mobileClosed = summarize("mobileClosed", closed);
    await page.click("#mobileLayersToggle");
    await page.waitForTimeout(600);
    try { await page.evaluate(() => window.MathJax?.typesetPromise?.()); } catch {}
    await page.waitForTimeout(400);
    const opened = await measure(page);
    out.mobileOpen = summarize("mobileOpen", opened);
    out.mobileOpen.rows = opened.rows.map((r) => ({
      text: r.text.slice(0, 80),
      display: r.display,
      labelSw: r.labelSw,
      labelW: r.labelW,
      overflow: r.labelOverflow,
      right: r.right,
      mj: r.mj,
    }));
    await page.close();
  }

  console.log(JSON.stringify(out, null, 2));
} finally {
  await browser.close();
  server.close();
}

