import { createServer } from "node:http";
import { readFileSync, existsSync, writeFileSync } from "node:fs";
import { extname, join } from "node:path";
import { createRequire } from "node:module";

const require = createRequire("/Users/sinchunyeung/.npm/_npx/e41f203b7505f1fb/node_modules/playwright/package.json");
const { chromium } = require("playwright");

const WEB = "/Users/sinchunyeung/.treehouse/simplification-of-trajectory-streams-bec452/3/simplification-of-trajectory-streams/web";
const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".png": "image/png",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json",
};

function makeStep(streamIdx, pi, p0) {
  return {
    stream_idx: streamIdx,
    pi,
    Gi: [
      [pi[0] - 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] - 0.4],
      [pi[0] + 0.4, pi[1] + 0.4],
      [pi[0] - 0.4, pi[1] + 0.4],
    ],
    buffer: [p0, pi],
    candidates: [{ grid_pt_idx: 0, alive: true, F: [], S: [] }],
  };
}

const p0 = [0, 0];
const p1 = [2, 1];
const p2 = [4, 0];
const ndjson = [
  {
    type: "header",
    eps: 0.9,
    delta: 500,
    grid_val: 12.5,
    r_val: 8.2,
    expected_frechet: 1.25,
    bbox: [-1, -1, 6, 3],
    stream: [p0, p1, p2],
  },
  {
    type: "prefix",
    data: {
      start_idx: 0,
      end_idx: 2,
      p0_idx: 0,
      p0,
      P: [[0.2, 0.2], [0.3, -0.1]],
      output: [p0, p2],
      steps: [makeStep(1, p1, p0), makeStep(2, p2, p0)],
    },
  },
  { type: "done", time_ms: 12.4, simplified: [p0, p2], frechet_distance: 0.41 },
].map((o) => JSON.stringify(o)).join("\n") + "\n";

const server = createServer((req, res) => {
  const url = new URL(req.url, "http://127.0.0.1");
  if (url.pathname === "/api/traces") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ traces: [{ id: 1, label: "Demo", n_points: 3 }] }));
    return;
  }
  if (url.pathname === "/api/trace/1" || url.pathname === "/api/trace") {
    res.writeHead(200, { "Content-Type": "application/x-ndjson" });
    res.end(ndjson);
    return;
  }
  if (url.pathname === "/api/frechet") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ distance: 0.4123 }));
    return;
  }
  const filePath = join(WEB, url.pathname === "/" ? "index.html" : url.pathname);
  if (!filePath.startsWith(WEB) || !existsSync(filePath)) {
    res.writeHead(404);
    res.end("not found");
    return;
  }
  res.writeHead(200, { "Content-Type": MIME[extname(filePath)] || "text/plain" });
  res.end(readFileSync(filePath));
});

async function loadTrace(page) {
  await page.waitForFunction(() => {
    const sel = document.getElementById("traceSelect");
    return sel && [...sel.options].some((o) => o.value === "1");
  }, { timeout: 8000 });
  await page.selectOption("#traceSelect", "1");
  await page.click("#loadBtn");
  await page.waitForFunction(() => document.body.classList.contains("playback-ready"), { timeout: 8000 });
  await page.waitForTimeout(500);
  try { await page.evaluate(() => window.MathJax?.typesetPromise?.()); } catch {}
  await page.waitForTimeout(400);
}

async function measureLayers(page) {
  return page.evaluate(() => {
    const vw = window.innerWidth;
    const sidebar = document.getElementById("sidebar");
    const row = document.getElementById("toggle-S")?.closest(".toggle-row");
    const label = row?.querySelector("label");
    const mj = [...(row?.querySelectorAll("mjx-container") || [])].map((n) => {
      const r = n.getBoundingClientRect();
      return { right: Math.round(r.x + r.width), w: Math.round(r.width), x: Math.round(r.x) };
    });
    const sr = sidebar.getBoundingClientRect();
    const lr = label.getBoundingClientRect();
    return {
      vw,
      scrollW: document.documentElement.scrollWidth,
      pageOverflowX: document.documentElement.scrollWidth > vw + 1,
      sidebarRight: Math.round(sr.x + sr.width),
      labelRight: Math.round(lr.x + lr.width),
      labelSw: label.scrollWidth,
      labelCw: label.clientWidth,
      mj,
      mjPastSidebar: mj.some((m) => m.right > sr.x + sr.width + 1),
      mjPastViewport: mj.some((m) => m.right > vw + 1),
    };
  });
}

await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
const port = server.address().port;
const browser = await chromium.launch({ channel: "chrome" });

try {
  const out = {};

  {
    const page = await browser.newPage();
    await page.setViewportSize({ width: 900, height: 700 });
    await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "domcontentloaded" });
    await loadTrace(page);
    await page.evaluate(() => document.getElementById("layersSection")?.scrollIntoView({ block: "center" }));
    await page.waitForTimeout(200);
    out.live900 = await measureLayers(page);
    await page.screenshot({
      path: join(WEB, "usability/desktop-layers-overflow-live.png"),
      fullPage: false,
    });
    await page.close();
  }

  {
    const page = await browser.newPage();
    await page.setViewportSize({ width: 1280, height: 800 });
    await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "domcontentloaded" });
    await loadTrace(page);
    await page.evaluate(() => document.getElementById("layersSection")?.scrollIntoView({ block: "center" }));
    await page.waitForTimeout(200);
    out.live1280 = await measureLayers(page);
    await page.screenshot({
      path: join(WEB, "usability/desktop-layers-overflow-1280-live.png"),
      fullPage: false,
    });
    await page.close();
  }

  {
    const page = await browser.newPage();
    await page.setViewportSize({ width: 640, height: 720 });
    await page.goto(`http://127.0.0.1:${port}/usability/desktop-layers-overflow.html`, { waitUntil: "domcontentloaded" });
    await page.screenshot({
      path: join(WEB, "usability/desktop-layers-overflow.png"),
      fullPage: true,
    });
    await page.close();
  }

  {
    const page = await browser.newPage();
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto(`http://127.0.0.1:${port}/`, { waitUntil: "domcontentloaded" });
    await loadTrace(page);
    await page.click("#mobileLayersToggle");
    await page.waitForTimeout(400);
    try { await page.evaluate(() => window.MathJax?.typesetPromise?.()); } catch {}
    await page.evaluate(() => document.getElementById("layersSection")?.scrollIntoView({ block: "center" }));
    await page.waitForTimeout(200);
    out.mobile390 = await measureLayers(page);
    await page.screenshot({
      path: join(WEB, "usability/mobile-layers-open-live.png"),
      fullPage: false,
    });
    await page.close();
  }

  writeFileSync("/tmp/layers-overflow-metrics.json", JSON.stringify(out, null, 2));
  console.log(JSON.stringify(out, null, 2));
} finally {
  await browser.close();
  server.close();
}

